WITH metrics AS (SELECT id, promo_code, ends_on, SUM(discount_pct) OVER (PARTITION BY promo_code ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount_pct, MIN(discount_pct) OVER w_hist AS promo_code_min_discount_pct FROM promotions WINDOW w_hist AS (PARTITION BY promo_code)) SELECT CASE WHEN cumulative_discount_pct >= 1 THEN 'LARGE' ELSE 'SMALL' END AS cumulative_discount_pct_tier, promo_code, DATE_TRUNC('YEAR', ends_on) AS year_start, SORT_ARRAY(COLLECT_SET(promo_code)) AS promo_code_list, MAX(cumulative_discount_pct) FILTER (WHERE promo_code = 'VIP') AS vip_max_cumulative_discount_pct, MAX(promo_code_min_discount_pct) AS max_promo_code_min_discount_pct, ROUND(AVG(cumulative_discount_pct), 2) AS avg_cumulative_discount_pct, SIZE(COLLECT_SET(promo_code)) AS num_promo_codes, COUNT(CASE WHEN promo_code = 'WELCOME5' THEN 1 END) AS welcome5_count FROM metrics GROUP BY CASE WHEN cumulative_discount_pct >= 1 THEN 'LARGE' ELSE 'SMALL' END, promo_code, DATE_TRUNC('YEAR', ends_on);
